import{_ as a,o as t,c as r,ae as s}from"./chunks/framework.RRduUuAx.js";const m=JSON.parse('{"title":"Projects","description":"","frontmatter":{"title":"Projects"},"headers":[],"relativePath":"projects/index.md","filePath":"projects/index.md"}'),o={name:"projects/index.md"};function i(l,e,n,c,d,h){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="projects" tabindex="-1">Projects <a class="header-anchor" href="#projects" aria-label="Permalink to &quot;Projects&quot;">​</a></h1><p>Things built or written outside the formal methods structure — personal tools, visual experiments, writing at various levels of finish, and work in progress.</p><p>These sit alongside the methods, frameworks, and tools on this site rather than within that hierarchy. Some are fully documented. Some are working notes. A few are ongoing.</p><hr><h2 id="tools-and-systems" tabindex="-1">Tools and systems <a class="header-anchor" href="#tools-and-systems" aria-label="Permalink to &quot;Tools and systems&quot;">​</a></h2><h3 id="loom" tabindex="-1"><a href="/projects/loom/">Loom</a> <a class="header-anchor" href="#loom" aria-label="Permalink to &quot;[Loom](/projects/loom/)&quot;">​</a></h3><p>A personal work tracker built around a single keystroke. Loom captures what I&#39;m working on with minimal friction and generates a structured weekly summary using a local AI model. Designed for sustained independent work rather than team task management.</p><p><em>Documentation: partial. Full prompt logic not public.</em></p><hr><h3 id="local-voice-assistant-for-kids" tabindex="-1"><a href="/projects/kids-voice-assistant/">Local voice assistant for kids</a> <a class="header-anchor" href="#local-voice-assistant-for-kids" aria-label="Permalink to &quot;[Local voice assistant for kids](/projects/kids-voice-assistant/)&quot;">​</a></h3><p>A voice-controlled assistant built for young children, using the Spotify API and a simplified Wikipedia layer. Designed to run locally, with no persistent data collection. Built for a specific household need; documented here as a replicable pattern.</p><p><em>Documentation: overview and architecture. Implementation detail partial.</em></p><hr><h3 id="semantic-layer-over-vinted" tabindex="-1"><a href="/projects/vinted-semantic-layer/">Semantic layer over Vinted</a> <a class="header-anchor" href="#semantic-layer-over-vinted" aria-label="Permalink to &quot;[Semantic layer over Vinted](/projects/vinted-semantic-layer/)&quot;">​</a></h3><p>An experiment in building a structured semantic layer over an unstructured second-hand marketplace. The goal is to make search and discovery behave more like a curated catalogue than a keyword index.</p><p><em>Work in progress. Notes only.</em></p><hr><h2 id="writing" tabindex="-1">Writing <a class="header-anchor" href="#writing" aria-label="Permalink to &quot;Writing&quot;">​</a></h2><h3 id="extending-tufte-the-bumped-stacked-bar-chart" tabindex="-1"><a href="/projects/bumped-stacked-bar/">Extending Tufte: the bumped stacked bar chart</a> <a class="header-anchor" href="#extending-tufte-the-bumped-stacked-bar-chart" aria-label="Permalink to &quot;[Extending Tufte: the bumped stacked bar chart](/projects/bumped-stacked-bar/)&quot;">​</a></h3><p>The stacked bar chart has a structural problem: it hides change over time for all but the bottom series. This piece introduces the bumped stacked bar chart as an extension of Tufte&#39;s visual vocabulary — a form that preserves proportion while making trajectory legible.</p><p><em>Polished.</em></p><hr><h3 id="small-multiples" tabindex="-1"><a href="/projects/small-multiples/">Small multiples</a> <a class="header-anchor" href="#small-multiples" aria-label="Permalink to &quot;[Small multiples](/projects/small-multiples/)&quot;">​</a></h3><p>Working notes on small multiples as an analytical form: when they work, when they fail, and what they reveal about the assumptions behind data visualisation.</p><p><em>Working notes.</em></p><hr><h3 id="claude-projects-as-semi-structured-workflows" tabindex="-1"><a href="/projects/claude-projects-workflows/">Claude Projects as semi-structured workflows</a> <a class="header-anchor" href="#claude-projects-as-semi-structured-workflows" aria-label="Permalink to &quot;[Claude Projects as semi-structured workflows](/projects/claude-projects-workflows/)&quot;">​</a></h3><p>Claude Projects allow context to persist across sessions, which makes them useful for something more specific than general assistance: semi-structured analytical workflows where state, constraints, and partial outputs accumulate over time. This piece documents that pattern.</p><p><em>Polished.</em></p><hr><h2 id="disclosure" tabindex="-1">Disclosure <a class="header-anchor" href="#disclosure" aria-label="Permalink to &quot;Disclosure&quot;">​</a></h2><p>As with the rest of this site, documentation here follows a layered approach. What is public supports interpretation and potential reuse. Full implementation detail — prompts, logic, internal structure — is not always included.</p>',32)])])}const p=a(o,[["render",i]]);export{m as __pageData,p as default};
